 const uint32_t inputRate=env("VW_INPUT_RATE",1200000),outputRate=env("VW_OUTPUT_RATE",300000),channels=env("VW_CHANNELS",5),lanes=env("VW_LANES",2),frames=env("VW_FRAMES",24),cpiMs=env("VW_CPI_MS",0),samples=cpiMs?uint32_t(uint64_t(inputRate)*cpiMs/1000):env("VW_SAMPLES",4096),tapsPerPhase=env("VW_TAPS_PER_PHASE",16),gapEvery=env("VW_GAP_EVERY",12),parityEvery=env("VW_PARITY_EVERY",1),parityLanes=env0("VW_PARITY_LANES",lanes),paced=env("VW_PACED",0),dequeInput=env("VW_DEQUE_INPUT",0),rasterHz=env("VW_RASTER_HZ",0);if(inputRate%outputRate||channels>8||lanes>blah2::wideband_gpu::maxLanes||parityLanes>lanes)throw std::invalid_argument("geometry");const uint32_t occupied=std::min(outputRate-1,uint32_t(outputRate*2/3));std::vector<double> offsets(lanes);for(uint32_t lane=0;lane<lanes;++lane)offsets[lane]=lanes==1?envd("VW_OFFSET_HZ",0):(rasterHz?double(int64_t(lane)-int64_t(lanes/2))*rasterHz:(-.4+.8*double(lane)/(lanes-1))*inputRate);
 blah2::wideband_gpu::Config config{inputRate,channels,samples,{}};std::vector<std::unique_ptr<blah2::channelizer::SubbandChannelizer>> cpu;for(size_t lane=0;lane<lanes;++lane){auto taps=blah2::wideband_gpu::designFilter(inputRate,outputRate,occupied,tapsPerPhase);config.lanes.push_back({99500000+lane*1000000,inputRate/outputRate,offsets[lane],std::move(taps)});cpu.push_back(std::make_unique<blah2::channelizer::SubbandChannelizer>(blah2::channelizer::SubbandChannelizer::Config{inputRate,outputRate,offsets[lane],double(occupied),tapsPerPhase},channels));}
