 uint64_t first=env("VW_FIRST",11);double worstRms=0,worstPeak=0;uint32_t misses=0,gaps=0,parityFrames=0;std::vector<double> times,stagingTimes,workerTimes;auto start=std::chrono::steady_clock::now();
